-- Heroes of Horror: tainted locations, dread terrain, hauntings, and mortuary terrain.
-- Source: Heroes of Horror, Chapter 4, pp. 68-76. Mechanical text is summarized; source pages remain authoritative.

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,summary,tags,mechanics) AS (VALUES
('hoh-tainted-locations','Tainted Locations','68','horror-environment','subsystem',1,0,
 'Tainted locations expose visitors to corruption or depravity, intensify evil magic, impede good and healing magic, animate corpses, and can be cleansed only by sustained hallow magic.',
 '["horror","environment","taint","location"]',
 '{"taint_type_guidance":{"undead_or_death":"corruption","evil_outsiders_or_human_evil":"depravity"},"initial_exposure":{"typical_increase":1,"severe_increase_options":["1d3","1d4"],"save":{"corruption":"Fortitude","depravity":"Will"},"typical_dc":20,"extreme_dc_options":[25,30],"success":"avoid or reduce taint increase as adjudicated"},"continued_exposure":{"interval_hours":24,"taint_increase":1,"save_dc":"10 + 5 per consecutive 24 hours of exposure"},"evil_spell":{"effective_caster_level_bonus":1,"will_save_dc":"15 + spell level","failure":"depravity +1"},"good_or_healing_spell":{"effective_caster_level_penalty":-1},"death":{"animation_delay":"1d4 hours","usual_result":"zombie of appropriate size","burning_corpse_prevents":true},"cleansing":{"spell":"hallow","required_duration":"1 year uninterrupted","unhallow_resets_progress":true,"hallow_radius_ft":40,"large_areas_require_multiple_castings":true}}'),
('hoh-abyssal-blackgrass','Abyssal Blackgrass','68-69','horror-environment','rule',1,0,
 'Abyssal blackgrass suppresses natural healing, halves magical healing, and can inflict corruption when evil magic is used nearby.',
 '["horror","environment","dread-effect","taint","healing"]',
 '{"clump_diameter_ft":1,"root_effect_radius_ft":50,"natural_healing":"impossible","magical_healing_multiplier":0.5,"evil_descriptor_spell":{"applies_to":["caster","subject"],"fortitude_dc":"10 + spell level","failure":"corruption +1"},"uprooting":{"ends_effect":false,"regrows_in":"1d4 days"},"permanent_removal":["dig up entire root system","blight spell","similar plant-destroying magic"]}'),
('hoh-blood-rock','Blood Rock','69','horror-environment','rule',1,0,
 'Blood rock increases weapon lethality for creatures standing on affected ground and can be transplanted to seed new areas.',
 '["horror","environment","dread-effect","critical-hit"]',
 '{"requirement":"attacker must touch affected ground","threat_range_multiplier":2,"does_not_stack_with":["Improved Critical","keen edge","keen weapon property"],"seeding":{"pounds_per_5ft_square":5,"activation_delay_hours":48,"moving_resets_activation_delay":true,"carrying_only_grants_combat_effect":false}}'),
('hoh-tainted-blood-rock','Tainted Blood Rock','69','horror-environment','rule',1,0,
 'Tainted blood rock combines blood rock lethality with a corruption risk whenever a creature scores a critical hit while standing on it.',
 '["horror","environment","dread-effect","critical-hit","taint"]',
 '{"inherits":"blood rock","evil_aura":"moderate","trigger":"score a critical hit while standing on tainted blood rock","save":"Fortitude","dc":25,"failure":"corruption +1"}'),
('hoh-charnel-bog','Charnel Bog','69-70','horror-environment','subsystem',1,0,
 'Charnel bogs impede good magic and turning, ruin rest, erode the will to leave, and can expose travelers to disease and corruption.',
 '["horror","environment","dread-effect","undead","taint"]',
 '{"spell_impedance":{"descriptors":["good","healing"],"check":"Spellcraft","dc":"15 + spell level","failure":"spell lost"},"turn_undead_check_penalty":-4,"rebuke_undead_check_profane_bonus":4,"camping":{"morning_condition":"fatigued","good_arcane_or_divine_spells_not_regained_hours":24,"hit_points_regained":0},"long_term":{"interval":"each consecutive week","save":"Will","dc":"10 + number of consecutive weeks","failure":{"cannot_leave_voluntarily":true,"desire_to_leave":false,"memories":"slowly fade","restoration":["limited wish","miracle","wish"]}},"common_hazards":["hauntings","cackle fever","mindfire"],"tainted_variant":{"entry_save":"Fortitude","dc":25,"success":"corruption +1","failure":"corruption +1d3"}}'),
('hoh-night-stone','Night Stone','70','horror-environment','rule',1,0,
 'Raw negative energy in night stone harms living creatures that remain close to a night-stone surface or object.',
 '["horror","environment","negative-energy","dread-effect"]',
 '{"affected":"living creature","distance_ft":5,"damage_per_round":"1d6","death_ward_protects":true,"examples":["floor","wall","statue"]}'),
('hoh-haunting-presence','Haunting Presence','70-71','haunting','subsystem',1,0,
 'An undead haunting presence is an immaterial undead identity bound to an unattended object or location, normally unreachable until manifested or exorcised.',
 '["horror","haunting","undead","poltergeist"]',
 '{"valid_anchor":{"object_attendance":"unattended","object_magic":"mundane normally; unattended magic items can be targeted with a save","object_size_min":"Tiny","object_size_max":"Huge","location_allowed":true},"unattended_magic_item_save_dc":"10 + 1/2 undead HD + undead Charisma modifier","awareness":{"see_ft":60,"hear_ft":60,"blindsight":false},"direct_state":{"normally_cannot_be_turned":true,"normally_cannot_be_rebuked":true,"normally_cannot_be_destroyed":true,"ends_by":["successful exorcism followed by destruction/removal","destruction of haunted object or location"]},"forms":{"under_5_hd":"one haunting form","at_least_5_hd":["impermanent home","poltergeist"]},"impermanent_home":{"manifestations_per_week":"undead HD","manifest_location":"anywhere in haunted location or closest empty square adjacent to haunted object","maximum_minutes_per_manifestation":"undead HD","return_to_presence_action":"move","while_manifested":"acts and can be damaged as normal undead","destroyed_while_manifested":"usually permanently eradicates presence","exceptions":"undead with special resistance to destruction such as ghosts or liches"},"poltergeist":{"moving_part_object_control":true,"maximum_object_speed":"undead normal-form speed","animate_static_object_requirement":{"minimum_hd":10,"minimum_charisma":17},"maximum_animated_object_cr":"undead CR","haunted_location_simultaneous_animated_objects":"undead HD"},"sentient_presence_can_speak":true,"notice_oddity":{"check":"Intelligence","dc":15}}'),
('hoh-exorcise-haunting-presence','Exorcising a Haunting Presence','71','haunting','procedure',1,0,
 'Exorcism forces a haunting presence into physical form so that normal methods such as turning or combat can affect it.',
 '["horror","haunting","exorcism","undead"]',
 '{"initial_ritual":{"actions":10,"action_type":"consecutive full-round actions","check":"Knowledge (religion)","dc":20,"interruption":"restart ritual"},"success":{"forced_physical_rounds":1,"next_action_options":["turn revealed undead","continue ritual"]},"continuation":{"check_each_round":"Knowledge (religion)","dc":20,"success":"remain physical 1 additional round"},"overrides":{"low_hd_poltergeist_only":true,"weekly_manifestations_exhausted":true}}'),
('hoh-haunted-site-effects','Haunted Site Effects','71-72','haunting','subsystem',1,0,
 'Environmental hauntings can manifest as fear, sickness, shadow harm, or telekinetic spell-like phenomena and can expose sleepers to depravity.',
 '["horror","haunting","fear","illusion","taint"]',
 '{"fear_manifestations":[{"result":"shaken","save":"Will","dc":12},{"result":"frightened","save":"Will","dc":15},{"result":"panicked","save":"Will","dc":18}],"odor_manifestations":[{"result":"sickened","save":"Fortitude","dc":13,"success":"negates"},{"result":"nauseated","save":"Fortitude","dc":18,"success":"sickened instead"}],"extreme_phantasms":[{"duplicates":"phantasmal killer","dc":16},{"duplicates":"weird","dc":23}],"shadow_harm":{"typical_real_damage":"1d6","unnatural_chill_options":["1d4 Strength damage","1d4 Dexterity damage","1 negative level"]},"telekinetic_duplicates":["mage hand","open/close","telekinesis","arcane lock","knock"],"telekinetic_resistance":"use the saving throw or other resistance roll of the duplicated spell","overnight_taint":{"save":"Will","dc":20,"failure":"depravity +1","more_severe_haunting_may_raise_dc":true}}'),
('hoh-exorcise-haunted-site','Exorcising a Haunted Site','72','haunting','procedure',1,0,
 'A ritual can make a haunted site temporarily vulnerable to dispelling and curse-breaking magic.',
 '["horror","haunting","exorcism","dispel"]',
 '{"ritual":{"actions":10,"action_type":"consecutive full-round actions","check":"Knowledge (religion)","dc":20},"success":{"vulnerable_rounds":1,"removal_methods":["dispel magic","remove curse","break enchantment"],"effective_caster_level":"minimum caster level required for the highest-level spell duplicated by the haunting"},"continuation":{"check_each_round":"Knowledge (religion)","dc":20,"success":"remain vulnerable 1 additional round"}}'),
('hoh-graveyard-terrain','Graveyard Terrain Features','72-75','mortuary-terrain','table',1,0,
 'Graveyard age guides the density of gravestones, mausoleums, memorials, trees, vaults, and walls.',
 '["horror","terrain","graveyard","mortuary"]',
 '{"feature_chance_percent":{"gravestone":{"new":25,"moderate":50,"ancient":75},"mausoleum":{"new":5,"moderate":10,"ancient":20},"statue_memorial":{"new":10,"moderate":15,"ancient":20},"massive_tree":{"new":"1 fixed feature","moderate":"1 fixed feature","ancient":"1 fixed feature"},"typical_tree":{"new":5,"moderate":5,"ancient":5},"vault":{"new":5,"moderate":10,"ancient":15},"wall":{"new":5,"moderate":5,"ancient":5}},"damaged_feature_chance_percent":25,"damaged_applies_to":["gravestone","mausoleum","statue memorial","wall"]}'),
('hoh-gravestone-terrain','Gravestone Terrain','74','mortuary-terrain','rule',1,0,
 'Standing gravestones hinder movement, grant limited cover-like defensive bonuses, and can be perched upon for higher ground.',
 '["horror","terrain","graveyard","gravestone"]',
 '{"movement_cost_squares":2,"same_square_bonus":{"armor_class":2,"reflex":1,"stacks_with_other_cover":false},"hardness":8,"hit_points":45,"perch":{"jump_dc":10,"balance_dc":15,"higher_ground_possible":true,"balance_modifiers":{"sloped":2,"old_or_crumbling":"+2 to +5","rain_or_moss":"+2 to +5"}},"flat_gravestone":{"movement_effect":false,"cover_effect":false}}'),
('hoh-mortuary-structures','Mortuary Structures','75-76','mortuary-terrain','rule',1,0,
 'Mausoleums, vaults, crypts, walls, and catacombs use durable stone construction and specific exploration checks.',
 '["horror","terrain","graveyard","mausoleum","catacomb"]',
 '{"statue":{"functions_as":"wide pillar providing cover","climb_dc":15},"graveyard_wall":{"usual_material":["masonry","superior masonry"],"height_ft":[4,8]},"mausoleum":{"usual_walls":"superior masonry","usual_floor":"flagstone","usual_doors":"securely locked stone"},"vault":{"entrance":"often secret door disguised as flat gravestone","search_dc":25},"crypt":"vault containing an altar","catacomb":{"natural_cave_wall":"unworked stone","constructed_wall":["hewn stone","masonry"],"sealed_graves":"superior masonry","wall_shelves_climb_dc":10,"usual_doors":"stone"}}'),
('hoh-plague-pit','Plague Pits','76','mortuary-terrain','rule',1,0,
 'A plague pit is a deep mass grave for plague victims; undead formed from such a pit carry the plague with their attacks.',
 '["horror","terrain","graveyard","plague","undead"]',
 '{"kind":"deep mass grave","contents":"plague victims","undead_from_pit":"invariably transmit the plague with their attacks"}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'hoh-rule-'||d.slug,'hoh-3.5',d.source_page,d.slug,d.name,d.summary,d.summary,0,NULL,1,
       d.category,d.kind,d.is_variant,d.default_enabled,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL);
